class DodavanjeArtiklaComponent {
  constructor(prodavnicaService, artikalService) {
    this.prodavnicaService = prodavnicaService;
    this.artikalService = artikalService;
    this.artikli = [];
    this.email = '';
    this.errors = [];
    this.successMessage = null;
  }
  ngOnInit() {
    const token = localStorage.getItem('token');
    if (token) {
      const decodedToken = jwt_decode(token);
      this.email = decodedToken.email;
    }
  }
  removeArtikal(index) {
    this.artikli.splice(index, 1);
    this.errors.splice(index, 1);
  }
  onFileChange(event) {
    const files = event.target.files;
    if (!files || files.length === 0) {
      return;
    }
    // Svaki upload = NOVI ARTIKAL
    const artikalIndex = this.artikli.length;
    const artikal = {
      images: [],
      currentImageIndex: 0,
      tip: '',
      kategorija: '',
      velicina: '',
      boja: '',
      cena: '',
      opis: '',
      aiLoading: true,
      aiError: ''
    };
    this.artikli.push(artikal);
    this.errors.push('');
    // Učitavanje svih slika u preview za ovaj artikal
    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      const reader = new FileReader();
      reader.onload = e => {
        artikal.images.push({
          file: file,
          preview: e.target.result
        });
      };
      reader.readAsDataURL(file);
    }
    // AI samo nad prvom slikom
    const firstFile = files[0];
    this.callAIForArtikal(artikalIndex, firstFile);
    // reset inputa da bi isti fajl mogao ponovo da se izabere ako treba
    event.target.value = '';
  }
  // Poziv AI klasifikacije ka backendu
  callAIForArtikal(index, fileForAI) {
    const artikal = this.artikli[index];
    if (!artikal) return;
    const file = fileForAI || artikal.images?.[0]?.file;
    if (!file) {
      artikal.aiLoading = false;
      artikal.aiError = 'Nema slike za AI klasifikaciju.';
      return;
    }
    this.artikalService.classifyArtikal(file).subscribe(res => {
      // očekujemo { tip, kategorija, boja }
      artikal.tip = res.tip;
      artikal.kategorija = res.kategorija;
      artikal.boja = res.boja;
      artikal.aiLoading = false;
      artikal.aiError = '';
    }, err => {
      console.error('AI klasifikacija nije uspela', err);
      artikal.aiLoading = false;
      artikal.aiError = 'AI nije uspeo da prepozna artikal, popunite ručno.';
    });
  }
  // Ručno menjanje slika u carousel-u
  nextImage(artikalIndex) {
    const artikal = this.artikli[artikalIndex];
    if (!artikal || !artikal.images || artikal.images.length === 0) return;
    artikal.currentImageIndex = (artikal.currentImageIndex + 1) % artikal.images.length;
  }
  prevImage(artikalIndex) {
    const artikal = this.artikli[artikalIndex];
    if (!artikal || !artikal.images || artikal.images.length === 0) return;
    artikal.currentImageIndex = (artikal.currentImageIndex - 1 + artikal.images.length) % artikal.images.length;
  }
  goToImage(artikalIndex, imageIndex) {
    const artikal = this.artikli[artikalIndex];
    if (!artikal || !artikal.images || artikal.images.length === 0) return;
    artikal.currentImageIndex = imageIndex;
  }
